'use client';

import { Section } from '@/components/Section';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Contact2 } from 'lucide-react';
import { Button } from '@/components/ui/button';

type ContactProps = {
    onSubmit: (e: React.FormEvent) => void;
};

export default function ContactSection({ onSubmit }: ContactProps) {
    return (
        <Section id="contact" data-aos="fade-up">
            <Card>
                <CardHeader>
                    <CardTitle><Contact2 className="mr-2 inline-block h-5 w-5" /> Contact</CardTitle>
                    <CardDescription>Get in touch with me.</CardDescription>
                </CardHeader>
                <CardContent>
                    <form onSubmit={onSubmit} className="grid gap-4">
                        <input type="text" name="name" placeholder="Your Name" className="p-2 border rounded" required />
                        <input type="email" name="email" placeholder="Your Email" className="p-2 border rounded" required />
                        <textarea name="message" rows={4} placeholder="Your Message" className="p-2 border rounded" required />
                        <Button type="submit">Send Message</Button>
                    </form>
                </CardContent>
            </Card>
        </Section>
    );
}
